// The published forms of the semantic layer (pages, JSON-LD, the combined JSON used by the app and the MCP
// server) are generated by scripts/semantics.mjs and committed. This fails when they are out of date: run
// `npm run semantics` after changing semantics/*.yaml.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { load, outputs } from "../scripts/semantics.mjs";

const ROOT = resolve(__dirname, "../..");

describe("generated semantic files", () => {
  const files = outputs(load());
  it.each(Object.keys(files))("%s is up to date (run npm run semantics)", (file) => {
    expect(readFileSync(resolve(ROOT, file), "utf8") === files[file]).toBe(true);
  });

  it("produces valid JSON-LD with only absolute IRIs", () => {
    for (const file of Object.keys(files).filter((f) => f.endsWith(".jsonld"))) {
      const doc = JSON.parse(files[file]);
      expect(doc["@context"], file).toBeTruthy();
      const ids = JSON.stringify(doc).match(/"@id":"[^"]*"/g) ?? [];
      expect(ids.filter((i) => !/"@id":"https?:\/\//.test(i)), file).toEqual([]);
    }
  });
});
